ype)==='percentage')>Percentage basis points</option></select></label><label>Discount value<input type="number" min="0" name="discount_value" value="{{ old('discount_value',$revision->discount_value ?? 0) }}"></label><label>Deposit percentage<input type="number" min="0" max="100" name="deposit_percentage" value="{{ old('deposit_percentage',$revision->deposit_percentage ?? 0) }}"></label><label class="span-2">Terms<textarea name="terms">{{ old('terms',$revision->terms) }}</textarea></label><label class="span-2">Exclusions<textarea name="exclusions">{{ old('exclusions',$revision->exclusions) }}</textarea></label><label class="span-2">Client responsibilities<textarea name="client_responsibilities">{{ old('client_responsibilities',$revision->client_responsibilities) }}</textarea></label><label class="span-2">Internal/client notes<textarea name="notes">{{ old('notes',$revision->notes) }}</textarea></label></div></section><div class="builder-actions"><span>Server-authoritative totals update after save.</span><button class="button primary">{{ $quotation->exists ? 'Save quotation' : 'Create draft' }}</button></div></form><template id="item-template"><div class="line-item" data-item><input data-name="name" placeholder="Item name" required><input data-name="quantity" value="1" inputmode="decimal"><input data-name="unit" value="item"><input data-name="unit_price_minor" value="0" type="number" min="0"><input data-name="tax_rate_basis_points" value="0" type="number" min="0" max="10000"><label class="check"><input data-name="is_optional" type="checkbox" value="1"> Optional</label><input data-name="is_selected" type="hidden" value="1"><button type="button" class="icon-button" data-remove-item>×</button></div></template></x-layouts.app>
